-- Career completeness, part 2a: each career's own description, steps into the career,
-- where people in it work, and (where its entrance exams do not already point to the right
-- colleges) the colleges that train for it. Agriculture, Defence, Design, Education, Engineering.
-- descr null = keep the existing description; cols null = colleges come from the career's exams.

update public.careers c set
  description = coalesce(v.descr, c.description),
  path_steps = string_to_array(v.steps, ' | '),
  top_employers = string_to_array(v.emp, ' | '),
  related_college_slugs = case when v.cols is null then c.related_college_slugs else string_to_array(v.cols, ' ') end
from (values
  -- Agriculture
  ('agricultural-extension-officer', null,
   'Class 12 with Biology (PCB) or Agriculture | B.Sc (Hons) Agriculture through ICAR AIEEA or your state agricultural university entrance | Field training and the Rural Agricultural Work Experience (RAWE) in final year | Apply for Agriculture Extension Officer / Agriculture Development Officer posts through your State PSC or state agriculture department | Optional: M.Sc in Agricultural Extension for senior and KVK roles',
   'State Agriculture Departments | Krishi Vigyan Kendras (KVKs) | ICAR institutes | NABARD | Agri-input companies (seeds, fertilisers) | NGOs in rural development', null),
  ('agronomist', null,
   'Class 12 with PCB or PCM | B.Sc (Hons) Agriculture through ICAR AIEEA or a state agricultural university entrance | M.Sc in Agronomy (ICAR AIEEA-PG) | Field trials and research projects | Join a seed, fertiliser or agritech company, or clear ICAR ASRB / state exams for scientist posts | Optional: PhD for research and teaching',
   'ICAR institutes | State Agricultural Universities | Seed companies (Mahyco, Syngenta) | Fertiliser companies | Agritech startups | State Agriculture Departments', null),
  ('food-technologist', null,
   'Class 12 with PCM or PCB | B.Tech Food Technology or B.Sc Food Science (JEE Main, ICAR AIEEA or state CETs) | Internships in food processing plants or quality labs | Learn FSSAI food-safety rules and HACCP | Join R&D, production or quality control | Optional: M.Tech / M.Sc for product development roles',
   'Nestle | ITC Foods | Britannia | Amul | PepsiCo | Haldiram''s | FSSAI | Food testing laboratories', null),
  ('horticulturist', null,
   'Class 12 with Biology | B.Sc (Hons) Horticulture through ICAR AIEEA or a state agricultural university | M.Sc Horticulture | Hands-on work in nurseries, orchards or polyhouses | Join a horticulture department, research station or private farm, or start your own nursery | Optional: PhD for research',
   'State Horticulture Departments | National Horticulture Board | ICAR horticulture institutes | Nurseries and floriculture firms | Fruit and vegetable export companies | Landscaping firms', null),

  -- Defence
  ('defence-scientist-drdo', null,
   'Class 12 with PCM | B.Tech / B.E. in a core branch (electronics, mechanical, computer science, aerospace) or M.Sc in Physics, Chemistry or Mathematics | A good GATE score | Apply for Scientist B through DRDO RAC (recruitment uses GATE scores and an interview) | Join a DRDO laboratory and work on a defence project | Grow through Scientist C to G with experience and research output',
   'DRDO laboratories (DRDL, ADE, ARDE, DEAL and others) | Aeronautical Development Agency | Bharat Electronics (BEL) | Hindustan Aeronautics (HAL) | BrahMos Aerospace', null),
  ('military-intelligence-officer', null,
   'Class 12 (PCM for NDA) or graduation (for CDS) | Clear NDA or CDS, then the SSB interview and medical | Train at NDA and IMA (or OTA for short service) | Get commissioned in the Indian Army | Volunteer for or be posted to the Intelligence Corps, then complete intelligence training | Serve in field intelligence units and staff appointments',
   'Indian Army Intelligence Corps | Defence Intelligence Agency | Military Intelligence directorate', null),
  ('territorial-army-officer', null,
   'Be a graduate aged 18-42, in gainful civilian employment or self-employed | Apply when the Territorial Army officer notification is published (written test, then interview at the Preliminary Interview Board) | Clear the SSB and the medical examination | Get commissioned as a Lieutenant in the Territorial Army | Do annual training camps while keeping your civilian job | Serve when your unit is embodied for duty',
   'Indian Army Territorial Army units (infantry, engineer and ecological battalions) | Departmental TA units of Railways, ONGC and IOC', null),

  -- Design
  ('fashion-designer', 'Creates clothing, footwear and accessory collections, from mood boards and sketches to fabric choice, samples and the final range. Works for fashion houses, export houses and brands, or runs their own label.',
   'Class 12 in any stream | Clear the NIFT entrance, NID DAT or a private design school''s test | B.Des in Fashion Design (4 years) | Intern with a designer, brand or export house | Build a portfolio and show at college fashion shows | Start as an assistant designer, then design your own collections or label',
   'Fabindia | Aditya Birla Fashion | Reliance Trends | Raymond | Manish Malhotra and other designer labels | Export houses | Myntra and Ajio private labels', null),
  ('graphic-designer', 'Turns ideas into visuals: logos, brand identities, posters, packaging, social media creatives and app graphics. Works with typography, colour and layout, mostly in tools such as Adobe Illustrator, Photoshop and Figma.',
   'Class 12 in any stream | Clear UCEED, NID DAT or a design school entrance (or join a diploma course) | B.Des in Communication or Graphic Design | Learn Illustrator, Photoshop, InDesign and Figma | Build an online portfolio and take internships or freelance work | Join a studio or agency, then grow to senior designer or art director',
   'Advertising agencies (Ogilvy, Dentsu, Leo Burnett) | Design studios | Brands and startups | Newspapers and publishers | Freelance clients', null),
  ('interior-designer', 'Plans interior spaces that are useful, safe and good-looking: layouts, materials, lighting, furniture and colour for homes, offices, shops and hotels. Works with clients, architects and contractors from concept to handover.',
   'Class 12 in any stream | Clear NID DAT, NIFT or a design / architecture school entrance | B.Des in Interior Design or B.Sc Interior Design | Learn AutoCAD, SketchUp and 3D rendering | Intern with an interior or architecture firm | Work as a junior designer, then run your own projects or studio',
   'Interior design studios | Architecture firms | Real estate developers | Hotel and retail chains | Furniture brands (IKEA, Godrej Interio) | Self-employed practice', null),
  ('product-designer', 'Designs everyday physical products, from appliances and furniture to medical devices, balancing how they work, look and can be manufactured. Uses sketches, CAD models and prototypes, and tests designs with users.',
   'Class 12 in any stream | Clear UCEED, NID DAT or CEED | B.Des / M.Des in Product or Industrial Design | Learn sketching, CAD (SolidWorks, Fusion 360) and prototyping | Internships with design or manufacturing companies | Work as a product designer, then lead design teams',
   'Godrej | Tata Elxsi | Titan | Bajaj | Design consultancies | Medical device makers | Startups', null),
  ('textile-designer', 'Designs fabrics: weaves, prints, embroidery and surface textures for clothing, home furnishings and technical textiles. Works with yarns, colour and looms, and with handloom clusters as well as mills.',
   'Class 12 in any stream | Clear the NIFT entrance or NID DAT | B.Des in Textile Design | Learn weaving, printing, dyeing and textile CAD | Intern with a mill, export house or handloom cluster | Join as a textile designer, then lead collections or start your own studio',
   'Arvind | Raymond | Welspun | Fabindia | Handloom and khadi boards | Export houses | Home furnishing brands', null),
  ('ui-ux-designer', 'Designs how apps and websites look and work. Researches what users need, sketches user flows and wireframes, builds clickable prototypes in Figma, and tests them with real people before developers build them.',
   'Class 12 in any stream | B.Des through UCEED / NID DAT, or any degree plus a UX course | Learn Figma, user research and interaction design | Build 3-4 case studies for your portfolio | Intern at a product company or agency | Work as a UI/UX designer, then senior or lead product designer',
   'Google | Microsoft | Flipkart | Swiggy | Zomato | Razorpay | Design agencies | Product startups', null),

  -- Education
  ('curriculum-developer', 'Designs what students learn and how: syllabi, textbooks, lesson plans, worksheets and assessments for schools, boards and EdTech companies, in line with the National Education Policy and board requirements.',
   'Graduation in the subject you want to work on | B.Ed or M.A. Education | Teach for a few years to understand classrooms | Learn instructional design and assessment | Join a publisher, school chain, board or EdTech company as a content or curriculum developer | Lead curriculum teams',
   'NCERT | CBSE | State SCERTs | Pearson and Oxford University Press | EdTech companies (BYJU''S, Unacademy) | School chains', 'ncert-delhi niepa-delhi tiss-mumbai azim-premji-university university-of-delhi rie-bhubaneswar'),
  ('edtech-entrepreneur', 'Builds a technology business that helps people learn: apps, online courses, test preparation, or tools for schools and teachers. Combines an understanding of how students learn with product, technology and business skills.',
   'Get a degree in any field (technology, education or business help) | Teach, tutor or work in an EdTech company to understand learners | Find a real learning problem and test a small solution | Build a team and a first product | Raise funding or grow from early revenue | Scale the company',
   'Self-employed (own startup) | EdTech companies (before founding) | Startup incubators (IIT, IIM, NASSCOM)', 'iit-bombay iit-delhi iim-ahmedabad iim-bangalore isb-hyderabad azim-premji-university'),
  ('education-consultant', 'Advises students and families on courses, colleges, entrance exams and study abroad, or advises schools on teaching quality and administration. Needs up-to-date knowledge of admissions and good counselling skills.',
   'Graduation (education, psychology or any subject) | Optional: M.A. Education or a counselling qualification | Learn admission systems in India and abroad (JoSAA, CUET, SAT, IELTS) | Work at a counselling firm, school or university admissions office | Build trust and a track record | Start your own consultancy',
   'Career counselling firms | Study-abroad consultancies | Schools and universities | EdTech companies | Self-employed', 'tiss-mumbai azim-premji-university niepa-delhi university-of-delhi christ-university'),
  ('educational-psychologist', 'Uses psychology to help children learn better: assesses learning difficulties, supports students with emotional or behavioural problems, and advises teachers and parents.',
   'Class 12 in any stream | B.A. / B.Sc Psychology | M.A. / M.Sc in Educational or School Psychology | Supervised practice in schools | Optional: RCI-recognised professional qualification and UGC NET for teaching | Work in schools, clinics or as a counsellor',
   'Schools | Special education centres | Child guidance clinics | NCERT and SCERTs | Universities', 'university-of-delhi tiss-mumbai jmi-delhi christ-university amity-psychology-noida rie-bhubaneswar'),
  ('historian', 'Researches the past using archives, inscriptions, manuscripts and other sources, and explains what happened and why. Teaches in universities, writes books, or works in museums, archives and heritage bodies.',
   'Class 12 (Humanities helps) | B.A. History through CUET UG | M.A. History through CUET PG | Clear UGC NET (for Assistant Professor) or NET-JRF (for a funded PhD) | PhD in your area of history | Teach, research, or join an archive, museum or heritage body',
   'Universities and colleges | Indian Council of Historical Research | National Archives of India | Archaeological Survey of India | Museums | Publishers', 'jnu university-of-delhi hindu-college-delhi bhu jadavpur-university amu presidency-college-chennai calcutta-university'),
  ('librarian', 'Manages libraries: selects and catalogues books and digital resources, runs library software, and helps students and researchers find information. Works in schools, colleges, universities, research labs and public libraries.',
   'Graduation in any subject | Bachelor of Library and Information Science (B.Lib.I.Sc, 1 year) | Master''s (M.Lib.I.Sc) | Learn library software (KOHA) and digital libraries | Clear UGC NET for university librarian posts, or state / KVS recruitment for school libraries | Grow to chief librarian',
   'Universities and colleges | Kendriya Vidyalayas and schools | Research institutes (CSIR, ICAR) | National Library | Public libraries | Corporate knowledge centres', 'university-of-delhi bhu amu jmi-delhi ignou-delhi madras-university mumbai-university'),
  ('online-course-creator', 'Teaches through online courses, videos and live classes on platforms such as YouTube, Udemy or their own website. Plans lessons, records and edits content, and builds an audience of learners.',
   'Master one subject or skill you can teach well | Learn to plan lessons and explain clearly | Learn basic video recording and editing | Start with free content (YouTube, Instagram) to find your audience | Launch paid courses on Udemy, Teachable or your own site | Grow with a team, or partner with an EdTech company',
   'Self-employed | YouTube and Udemy | EdTech companies (Unacademy, Physics Wallah) | Corporate training firms', null),
  ('professor', 'Teaches undergraduate and postgraduate students, guides PhD scholars and does research in their subject. Promotion depends on teaching, publications and research projects.',
   'Bachelor''s and master''s degree in your subject (at least 55% in master''s) | Clear UGC NET or CSIR NET (or SLET/SET for state universities) | PhD | Publish research papers | Apply for Assistant Professor posts | Grow to Associate Professor and Professor',
   'Central universities | State universities | IITs, NITs and IISERs | Private universities | Research institutes', null),
  ('school-principal', 'Leads a school: plans academics, manages teachers and staff, handles admissions and budgets, and works with parents and the board. Principals usually come from long teaching experience.',
   'Graduation and post-graduation in a subject | B.Ed (and M.Ed helps) | Teach for 8-10 years or more | Take on roles such as head of department or vice-principal | Apply for principal posts (KVS / NVS recruitment for central schools, or private school boards) | Lead and improve the school',
   'Kendriya Vidyalayas | Navodaya Vidyalayas | State government schools | Private school chains (DPS, Ryan) | International schools', 'niepa-delhi tiss-mumbai azim-premji-university university-of-delhi rie-bhubaneswar ignou-delhi'),
  ('social-worker', 'Helps individuals, families and communities facing poverty, illness, disability, abuse or discrimination. Works on the ground with NGOs, hospitals, government schemes and companies'' CSR programmes.',
   'Class 12 in any stream | Bachelor of Social Work (BSW) or any graduation | Master of Social Work (MSW) through TISSNET or a university entrance | Field placements with NGOs and hospitals | Choose an area: health, children, community development, HR or disaster relief | Work with an NGO, hospital or CSR team, or lead a project',
   'NGOs (CRY, Pratham, Goonj) | Hospitals | UNICEF and WHO projects | Company CSR teams | Government welfare departments', null),
  ('sports-coach', null,
   'Play your sport seriously through school, district and state levels | Class 12, then B.P.Ed / B.Sc Physical Education or a sports coaching course | Diploma in Sports Coaching from NSNIS Patiala or a SAI centre, or a federation coaching licence | Assist a senior coach at an academy or school | Earn higher coaching certifications | Coach a school, academy, state or national team',
   'Sports Authority of India | Schools and colleges | Sports academies | State and national federations | IPL and other league teams', 'nsnis-patiala lnipe-gwalior tnpesu-chennai amity-sports-noida sai-national'),

  -- Engineering
  ('aerospace-engineer', 'Designs, builds and tests aircraft, helicopters, satellites, rockets and their engines and systems. Works on aerodynamics, structures, propulsion and avionics, in labs, design offices and test facilities.',
   'Class 12 with PCM | B.Tech in Aerospace / Aeronautical Engineering through JEE Main / JEE Advanced | Internships at HAL, ISRO, DRDO or aviation firms | Clear GATE for M.Tech or PSU jobs, or the ISRO / DRDO scientist recruitment | Join as a design, test or maintenance engineer | Specialise and grow to senior engineer or scientist',
   'ISRO | DRDO | HAL | National Aerospace Laboratories | Boeing India | Airbus India | Tata Advanced Systems | Airlines and MROs', 'iit-bombay iit-madras iit-kanpur iit-kharagpur iisc-bangalore'),
  ('biomedical-engineer', null,
   'Class 12 with PCM (Biology helps) | B.Tech Biomedical Engineering through JEE Main or state CETs | Internships with hospitals or medical device companies | Learn medical instrumentation, imaging and regulatory standards | Join as a biomedical / clinical engineer or in device R&D | Optional: M.Tech or MS for research',
   'GE HealthCare | Siemens Healthineers | Philips | Medtronic | Hospitals (AIIMS, Apollo) | Medical device startups', null),
  ('chemical-engineer', 'Designs and runs the processes that turn raw materials into fuels, chemicals, medicines, fertilisers and food. Works on plant design, process safety, efficiency and pollution control.',
   'Class 12 with PCM | B.Tech Chemical Engineering through JEE Main / JEE Advanced or BITSAT | Internships in refineries or chemical plants | Clear GATE for PSU jobs (IOCL, ONGC, BPCL) or M.Tech | Join as a process or production engineer | Grow to plant manager or R&D lead',
   'Indian Oil | ONGC | Reliance Industries | BPCL | Tata Chemicals | Dr. Reddy''s | Asian Paints | UPL', null),
  ('civil-engineer', 'Plans, designs and builds roads, bridges, buildings, dams, railways and water systems, and makes sure they are safe and last. Works in design offices and on construction sites.',
   'Class 12 with PCM | B.Tech Civil Engineering through JEE Main or your state CET | Internships with construction or design firms | Learn AutoCAD, STAAD Pro and site work | Clear GATE, SSC JE, state AE exams or UPSC ESE for government jobs | Work as a site / design engineer, then project manager',
   'L&T Construction | Tata Projects | NHAI | CPWD | Railways | State PWDs | Shapoorji Pallonji | Afcons', null),
  ('electrical-engineer', 'Designs and maintains systems that generate, transmit and use electricity: power plants, grids, motors, electric vehicles and building wiring. Works on safety, efficiency and renewable energy.',
   'Class 12 with PCM | B.Tech Electrical Engineering through JEE Main or your state CET | Internships at power plants or electrical firms | Clear GATE for PSUs (NTPC, Power Grid) or SSC JE / state AE exams | Join as a design, site or maintenance engineer | Grow to senior engineer or project manager',
   'NTPC | Power Grid | Tata Power | Adani Power | Siemens | ABB | Schneider Electric | State electricity boards', null),
  ('electronics-engineer', null,
   'Class 12 with PCM | B.Tech in Electronics and Communication through JEE Main, BITSAT, VITEEE or state CETs | Learn circuits, embedded systems and VLSI basics | Internships at semiconductor or telecom firms | Clear GATE for PSUs (BEL, ISRO) or M.Tech, or join a company directly | Work in chip design, embedded systems or telecom',
   'Intel | Qualcomm | Texas Instruments | Samsung R&D | BEL | ISRO | Tata Elxsi | Bharti Airtel', null),
  ('mechanical-engineer', 'Designs, builds and maintains machines: engines, vehicles, turbines, manufacturing equipment and HVAC systems. One of the broadest engineering branches, used in almost every industry.',
   'Class 12 with PCM | B.Tech Mechanical Engineering through JEE Main or your state CET | Internships in manufacturing or automobile companies | Learn CAD (SolidWorks, CATIA) and manufacturing processes | Clear GATE for PSUs or M.Tech, or join a company through campus placement | Grow to design lead or plant manager',
   'Tata Motors | Mahindra | Maruti Suzuki | L&T | BHEL | Bosch | Larsen & Toubro | Indian Railways', null),
  ('metallurgical-engineer', 'Works with metals and materials: extracting them from ores, making alloys such as steel, and testing how they behave under heat and stress. Improves strength, cost and recycling of materials.',
   'Class 12 with PCM | B.Tech Metallurgical and Materials Engineering through JEE Main / JEE Advanced | Internships at steel plants | Clear GATE for PSU jobs (SAIL, NMDC) or M.Tech | Join as a process, quality or R&D engineer | Grow to plant or research lead',
   'Tata Steel | SAIL | JSW Steel | Hindalco | Vedanta | NMDC | DRDO labs', null),
  ('robotics-engineer', 'Designs and programs robots and automated systems used in factories, warehouses, hospitals and space. Combines mechanical design, electronics, sensors and software such as ROS and machine learning.',
   'Class 12 with PCM | B.Tech in Mechanical, Electronics, Mechatronics or Robotics through JEE Main | Build robots in college clubs and competitions | Learn embedded programming, ROS and control systems | Internships with automation companies | Join as a robotics or automation engineer; M.Tech helps for R&D',
   'ABB | Fanuc | Addverb | GreyOrange | Tata Elxsi | ISRO | Automation startups', null),
  ('agricultural-engineer', null,
   'Class 12 with PCM (or PCM with Biology) | B.Tech Agricultural Engineering through JEE Main or ICAR AIEEA | Internships in farm machinery or irrigation projects | Clear GATE (Agricultural Engineering paper) or state AE exams for government jobs | Join as a farm machinery, irrigation or food-processing engineer | Optional: M.Tech for research',
   'Mahindra Farm Equipment | John Deere | Jain Irrigation | State Agriculture and Irrigation Departments | ICAR institutes | Food processing companies', 'iit-kharagpur tnau-coimbatore pau-ludhiana gbpuat-pantnagar ouat-bhubaneswar'),
  ('textile-engineer', null,
   'Class 12 with PCM | B.Tech Textile Technology through JEE Main or your state CET | Internships in spinning, weaving or processing mills | Learn quality control and production planning | Join a mill or apparel company as a production or quality engineer | Grow to plant or merchandising manager',
   'Arvind | Raymond | Welspun | Vardhman | Reliance (polyester) | Grasim | Apparel export houses', 'government-college-of-engineering-textile-technology-serampore iit-delhi vjti-mumbai psg-tech')
) as v(slug, descr, steps, emp, cols)
where c.slug = v.slug;
